/// One layer of one frame, scaled from the 9-unit box to the view.
struct IC5Shape: Shape {
    let path: Path
    nonisolated func path(in r: CGRect) -> Path {
        let s = min(r.width, r.height) / 9
        let t = CGAffineTransform(translationX: r.minX + 0.5 * s, y: r.minY + 0.5 * s).scaledBy(x: s, y: s)
        return path.applying(t)
    }
}

/// One icon, drawn at `size` points. `on` is the chosen state: changing it walks the frames there (about a
/// quarter of a second, the page's quick move); a looped icon plays while it is on screen.
struct Icon5: View {
    let key: String
    var on: Bool = false
    var ink: Color = .black
    var size: CGFloat = 20

    @State private var from = 0
    @State private var to = 0
    @State private var t0 = Date.distantPast
    @State private var moving = false
    @State private var gen = 0
    @Environment(\.accessibilityReduceMotion) private var still
    @Environment(\.layoutDirection) private var direction

    private static let seconds: Double = 0.24
    /// back and forward point the way you go: right to left they point the other way (Apple's rule for direction).
    /// A forward turned a quarter to point down still points down: right to left the turn goes the other way too.
    private var flips: Bool { direction == .rightToLeft && (key == "back" || key == "forward") }
    /// the gear's 18 frames are an eighth of a turn: 18 a second is one turn in 8 seconds
    private static func fps(_ key: String) -> Double { key == "settings-open" ? 18 : 30 }

    private var icon: IC5Icon? { IC5.all[key] ?? IC5.extra[key] ?? IC5.drawn[key] }   // extra: TabIconsTest.swift (29 Oct); drawn: IconsDrawn.swift (18.4)

    private func frameIndex(at date: Date) -> Int {
        guard let ic = icon, !ic.frames.isEmpty else { return 0 }
        let n = ic.frames.count
        if ic.loop { return still ? 0 : Int(date.timeIntervalSinceReferenceDate * Self.fps(key)) % n }
        // OUTSIDE ITS MOTION IT IS THE STATE IT IS IN (Slice 43, audit Q10): not the last change it heard of. Two
        // changes in one frame (the search opened and closed at once) can lose one (SwiftUI: "onChange(of: Bool)
        // action tried to update multiple times per frame"), and the gear stayed an X with nothing open
        if !moving { return on ? n - 1 : 0 }
        let k = min(1, max(0, date.timeIntervalSince(t0) / Self.seconds))
        return min(n - 1, max(0, Int((Double(from) + Double(to - from) * k).rounded())))
    }

    private func fill(_ c: String) -> Color {
        switch c {
        case "#d94f3d": return Palette.red
        case "#ffe04a": return Palette.yellow
        case "#ffffff": return .white
        case "#78aef8": return Palette.blue
        case "#d4e249": return Palette.lime
        case "glass":   return Color.white.opacity(0.62)
        default:        return ink
        }
    }

    var body: some View {
        let loops = icon?.loop ?? false
        TimelineView(.animation(minimumInterval: 1.0 / 60, paused: !((loops && !still) || moving))) { ctx in
            let f = frameIndex(at: ctx.date)
            let layers = (icon.map { f < $0.frames.count ? $0.frames[f] : [] }) ?? []
            ZStack {
                ForEach(Array(layers.enumerated()), id: \.offset) { _, l in
                    IC5Shape(path: l.path).fill(fill(l.colour), style: FillStyle(eoFill: true))
                }
            }
        }
        .frame(width: size, height: size)
        // the drawings are the same in every language: a right-to-left layout moves them, never flips them, except
        // the two that say which way you go
        .environment(\.layoutDirection, .leftToRight)
        .scaleEffect(x: flips ? -1 : 1, y: 1)
        .onAppear {
            let last = max(0, (icon?.frames.count ?? 1) - 1)
            from = on ? last : 0; to = from
        }
        .onChange(of: on) { old, now in
            let last = max(0, (icon?.frames.count ?? 1) - 1)
            if still { from = now ? last : 0; to = from; return }
            // from where it is drawn: mid-motion, the frame it is on; at rest, the state it was in
            from = moving ? frameIndex(at: Date()) : (old ? last : 0); to = now ? last : 0; t0 = Date(); moving = true
            // only the latest change ends the motion (an earlier one's end stopped a later motion half way)
            gen &+= 1
            let g = gen
            Task { @MainActor in
                try? await Task.sleep(for: .seconds(Self.seconds + 0.05))
                if gen == g { moving = false }
            }
        }
        .onChange(of: key) { _, _ in
            let last = max(0, (icon?.frames.count ?? 1) - 1)
            from = on ? last : 0; to = from
        }
        .accessibilityHidden(true)
    }
}
